// One typed schema for every setting; unknown keys are dropped, missing ones get defaults.
export const Settings = z.object({
  version: z.literal(2).default(2),
  theme: z.enum(["light", "dark", "system"]).default("system"),
  fontSize: z.number().int().min(10).max(24).default(14),
  telemetry: z.boolean().default(false),
  editor: z.object({
    tabSize: z.number().int().min(1).max(8).default(2),
    wordWrap: z.boolean().default(true),
  }).default({}),
  sync: z.object({
    enabled: z.boolean().default(false),
    intervalMin: z.number().int().min(5).default(15),
  }).default({}),
});

export type Settings = z.infer<typeof Settings>;

export function parseSettings(raw: unknown): Settings {
  return Settings.parse(raw ?? {});
}
